#!/usr/bin/env bash
# Patch 93 voor hrmforce-site: alle oude redirects echt laten werken.
#
#   bash toepassen-93.sh
#
# Search Console meldde 396 adressen als 404 (validatie mislukt), 15 als
# redirectfout en 2 als soft 404. Oorzaak: Cloudflare Pages paste van
# public/_redirects alleen de eerste 100 regels toe; regel 101 tot en met 855
# werden stil genegeerd.
#
# 1. De redirects draaien nu in functions/_middleware.js. Bron blijft één
#    tekstbestand: src/data/redirects.txt (voorheen public/_redirects).
# 2. Exacte regels gelden altijd, wildcards pas na een 404, dus een wildcard
#    kan geen echte pagina meer overschrijven (dat gaf de redirectfouten).
# 3. Nieuwe patronen: /feed/, /page/N/, categoriemappen in het kenniscentrum,
#    /assessment/<naam>/ naar /assessments/<naam>/ (de soft 404's), oude
#    uploads naar /media/ of /documenten/, wp-admin en plugins geven 410.
# 4. Zes nieuwe regels voor adressen die nergens onder vielen.
set -euo pipefail
cd "$(dirname "$0")"
[ -f public/_routes.json ] || { echo "Draai dit vanuit de hoofdmap van hrmforce-site."; exit 1; }

cat > /tmp/93.b64 <<'B64EOF'
