Redirects via middleware: alle 855 regels in plaats van de eerste 100

Cloudflare Pages paste van public/_redirects alleen de eerste 100 regels
toe. Search Console meldde daardoor 396 oude adressen als 404. De regels
staan nu in src/data/redirects.txt en functions/_middleware.js voert ze
allemaal uit: exacte regels altijd, wildcards en WordPress-patronen pas na
een 404. Ook opgelost: de soft 404's op /assessment/<naam>/ en zes adressen
zonder regel.

